window.AUTH=window.AUTH||{};window.AUTH["23-971"]={"d":"23-971","id":"2024/23-971","n":"Waetzig v. Halliburton Energy Services, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner Gary Waetzig","date":"2024-11-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-971/332068/20241118132019967_23-971%20Brief%20for%20Petitioner.pdf","side":"pet","n":91},{"k":"respondent","label":"Brief of respondent Halliburton Energy Services, Inc.","date":"2024-12-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-971/335492/20241218142610310_Waetzig%20v.%20Halliburton%20-%20Brief%20for%20Respondent.pdf","side":"res","n":107},{"k":"reply","label":"Reply of petitioner Gary Waetzig","date":"2025-01-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-971/336508/20250103114805695_23-971%20Reply.pdf","side":"pet","n":54}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r14_6kg7.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Axon Enter., Inc. v. Fed. Trade Comm’n","cite":"598 U.S. 175","y":2023,"id":"2022/21-86","sc":1,"sum":"The statutory review schemes set out in the Securities Exchange Act and Federal Trade Commission Act do not displace a district court’s federal-question jurisdiction over claims challenging as unconstitutional the structure or existence of the SEC or FTC.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47"}},{"t":"case","label":"Babbitt v. Sweet Home Chapter of Communities for a Great Oregon","cite":"515 U.S. 687","y":1995,"id":"1994/94-859","sc":1,"sum":"The Supreme Court held that habitat modification is a legitimate application of the word \"harm.\" First, the Court found that the Court of Appeals was incorrect in assuming that the words in the definition of \"take\" only apply to actions involving direct contact with endangered animals.","sumSrc":"Oyez","by":{"0":"21, 22"}},{"t":"case","label":"Badgerow v. Walters","cite":"596 U.S. 1","y":2022,"id":"2021/20-1143","sc":1,"op":4,"ar":15,"sum":"Federal jurisdiction in a petition to compel arbitration under Section 4 of the Federal Arbitration Act is determined by “looking through” the petition to the jurisdictional basis of the “underlying substantive controversy,” Vaden v. Discover Bank, 556 U. S. 49, 62, but that approach does not apply to petitions to confirm or vacate arbitral awards under Sections 9 and 10 of the FAA.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"6","1":"2, 6, 10, 16, 17, 20, 40","2":"4"}},{"t":"case","label":"Bell v. New Jersey","cite":"461 U.S. 773","y":1983,"id":"1982/81-2125","sc":1,"sum":"Respondent States received funds as part of the federal grant-in-aid program under Title I of the Elementar, and Secondary Education Act of 1965 (ESEA), a program designed to improve the educational opportunities available to disadvantaged children. Subsequently, federal auditors determined that each State had misapplied the funds. The Education Appeal Board (Board), while modifying the auditors' findings, assessed …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"sum":"The District Court properly invoked its inherent power in assessing as a sanction for Chambers' bad-faith conduct the attorney's fees and related expenses paid by NASCO.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Coca-Cola Co. v. City of Atlanta","cite":"110 S.E. 730","y":1922,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./110/730/","by":{"0":"18"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","1":"24","2":"8"}},{"t":"case","label":"Commonwealth, to Use of Beckingham v. Magee","cite":"73 A. 346","y":1909,"court":"Pa.","url":"https://www.courtlistener.com/c/A./73/346/","by":{"0":"36","1":"46"}},{"t":"case","label":"Confederated Tribes & Bands of Yakama Nation v. Okanogan County","cite":"16 Wash App. 2d 1030","y":2021,"url":"https://www.courtlistener.com/c/Wash%20App.%202d/16/1030/","by":{"0":"23"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"sum":"Respondents, the defendants in a District Court suit instituted by petitioner law firm on behalf of a client, filed a motion to dismiss the complaint as having no basis in fact and a motion for sanctions under Federal Rule of Civil Procedure 11 on the ground that the firm had not made sufficient prefiling inquiries to support the complaint's allegations. Rule 11-after specifying, interalia, that an attorney's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 42"}},{"t":"case","label":"Davenport v. Hardman","cite":"192 S.E. 11","y":1937,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./192/11/","by":{"0":"32"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"op":3,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"op":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"0":"21","1":"35, 41"}},{"t":"case","label":"Fish Mkt. Nominee Corp. v. Pelofsky","cite":"72 F.3d 4","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/72/4/","by":{"0":"21"}},{"t":"case","label":"Fla. Dep’t of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"sum":"The Court held 7-2 that the plain meaning of the statute indicates that it only applies to confirmed asset sales, not \"pre-confirmation\" sales.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Friel v. Alewel","cite":"298 S.W. 762","y":1927,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W./298/762/","by":{"0":"24"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"593 U.S. 522","y":2021,"id":"2020/19-123","sc":1,"sum":"Philadelphia’s refusal to contract with Catholic Social Services for the provision of foster care services unless CSS agrees to certify same-sex couples as foster parents violates the Free Exercise Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Gillespie v. U.S. Steel Corp.","cite":"379 U.S. 148","y":1964,"id":"1964/10","sc":1,"sum":"Petitioner, administratrix, whose son died while working on respondent's ship docked in Ohio, sued in a federal district court, claiming for the estate a right to recover damages for the benefit of herself and decedent's dependent brother and sisters for wrongful death. This claim was based on negligence under the Jones Act and on unseaworthiness under the general maritime law coupled with the Ohio wrongful death …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","1":"29"}},{"t":"case","label":"Graham v. Superior Mines","cite":"49 P.2d 443","y":1935,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/49/443/","by":{"0":"33"}},{"t":"case","label":"Hall v. Hall","cite":"584 U.S. 59","y":2018,"id":"2017/16-1150","sc":1,"op":4,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"0":"10, 13, 30, 38, 40, 41, 45","1":"11, 22, 24, 29","2":"8, 16–17"}},{"t":"case","label":"Harjo v. Black","cite":"153 P. 1137","y":1915,"court":"Okla.","url":"https://www.courtlistener.com/c/P./153/1137/","by":{"0":"36","1":"46"}},{"t":"case","label":"Harrington v. Purdue Pharma L. P.","cite":"144 S. Ct. 2071","y":2024,"id":"2023/23-124","sc":1,"sum":"The bankruptcy code does not authorize a release and injunction that, as part of a plan of reorganization under Chapter 11, effectively seek to discharge claims against a nondebtor without the consent of affected claimants.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24"}},{"t":"case","label":"Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"sum":"The phrase \"any other final action\" in § 307 (b) (1) is to be construed in accordance with its literal meaning so as to reach any action of the Administrator that is final, not just final actions of the Administrator similar to actions under the specifically enumerated provisions that precede the catchall phrase in the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Hazel-Atlas Glass Co. v. Hartford-Empire Co.","cite":"322 U.S. 238","y":1944,"id":"scdb/1943-040","sc":1,"sum":"Upon appeal from a judgment of the District Court denying relief in a suit by Hartford against Hazel for infringement of a patent, the Circuit Court of Appeals in 1932 held Hartford's patent valid and infringed, and upon its mandate the District Court entered judgment accordingly. In 1941, Hazel commenced in the Circuit Court of Appeals this proceeding, wherein it conclusively appeared that Hartford, through …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"43"}},{"t":"case","label":"Hoodless v. Winter","cite":"16 S.W. 427","y":1891,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W./16/427/","by":{"0":"37"}},{"t":"case","label":"Horne v. Flores","cite":"557 U.S. 433","y":2009,"id":"2008/08-289","sc":1,"sum":"The Court found that the lower court incorrectly analyzed Rule 60(b)(5), which allows a party to seek relief from a judgment if a significant change in the law has occurred.","sumSrc":"Oyez","by":{"0":"3, 15, 16"}},{"t":"case","label":"Jackson v. Waldron","cite":"5 F. 245","y":1880,"court":"C.C.W.D. Tenn.","url":"https://www.courtlistener.com/c/F./5/245/","by":{"0":"36","1":"44, 45"}},{"t":"case","label":"Jacobellis v. Ohio","cite":"378 U.S. 184","y":1964,"id":"1963/11","sc":1,"sum":"The judgment is reversed. Pp. 184-198. 173 Ohio St. 22, 179 N. E. 2d 777, reversed. MR. JUSTIcE BRENNAN, joined by MR. JUSTIcE GOLDBERG, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7"}},{"t":"case","label":"John Simmons Co. v. Grier Brothers","cite":"258 U.S. 82","y":1922,"id":"scdb/1921-053","sc":1,"op":1,"ar":1,"sum":"1. A bill of review is called for only after a final decree adjudicating upon the entire merits and leaving nothing further to be ^one except the execution of it.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"sum":"The saving clause in 28 U. S. C. §2255(e) does not allow a prisoner asserting an intervening change in the interpretation of a criminal statute to circumvent the Antiterrorism and Effective Death Penalty Act of 1996’s restrictions on second or successive §2255 motions by filing a habeas petition under §2241.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39"}},{"t":"case","label":"Keith Mfg. Co. v. Butterfield","cite":"955 F.3d 936","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/955/936/","by":{"0":"28"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"op":3,"ar":4,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","1":"2, 10, 15, 16, 18, 19, 20, 37, 40, 50","2":"2, 4–5"}},{"t":"case","label":"Krupski v. Costa Crociere S. p. A.","cite":"560 U.S. 538","y":2010,"id":"2009/09-337","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals' interpretation of Federal Rule of Civil Procedure 15(c)(1)(C), which permits an amended complaint to relate back to when the amendment corrects a \"mistake concerning the proper party's identity,\" undermined the fundamental purpose of the rule.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Lacey v. Citizens’ Lumber & Supply Co.","cite":"248 N.W. 378","y":1933,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W./248/378/","by":{"0":"34"}},{"t":"case","label":"Link v. Anselm","cite":"1910 WL 3096","y":1910,"court":"Pa.","by":{"0":"37"}},{"t":"case","label":"Link v. Wabash R, Co.","cite":"370 U.S. 626","y":1962,"id":"1961/422","sc":1,"sum":"The Court held that a court has the right to clear its calendar of cases that have been dormant because of inaction on the part of the plaintiff without any motion from the defense. This right has long been understood as one of the inherent powers of the court and no law explicitly restricts it.","sumSrc":"Oyez","by":{"0":"38, 42, 46","1":"49"}},{"t":"case","label":"Lusas v. St. Patrick’s Roman Cath. Church Corp. of Waterbury","cite":"193 A. 204","y":1937,"court":"Conn.","url":"https://www.courtlistener.com/c/A./193/204/","ar":1,"by":{"0":"10, 32, 33, 35, 40, 48","1":"46, 47","2":"18–19"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Millar v. Whittington","cite":"105 S.E. 907","y":1921,"court":"W. Va.","url":"https://www.courtlistener.com/c/S.E./105/907/","by":{"0":"17"}},{"t":"case","label":"Miller v. Fortune Ins. Co.","cite":"484 So. 2d 1221","y":1986,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/484/1221/","by":{"0":"23"}},{"t":"case","label":"National Power & Paper Co. v. Rossman","cite":"142 N.W. 818","y":1913,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./142/818/","by":{"0":"38"}},{"t":"case","label":"Nelson v. Adams USA, Inc.","cite":"529 U.S. 460","y":2000,"id":"1999/99-502","sc":1,"sum":"The Court held that the District Court erred in amending the judgment immediately upon permitting the amendment of the pleading.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Occidental Life Ins. Co. v. Niendorf","cite":"44 P.2d 1099","y":1935,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/44/1099/","by":{"0":"34"}},{"t":"case","label":"Palace Hardware Co. v. Smith","cite":"66 P. 474","y":1901,"court":"Cal.","url":"https://www.courtlistener.com/c/P./66/474/","op":2,"by":{"0":"10, 39, 40","1":"47","2":"18"}},{"t":"case","label":"Pedrina v. Chun","cite":"987 F.2d 608","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/987/608/","sum":"Holding district court lacked authority to require Rule 41(a)(1) dismissal by motion rather than notice.","sumSrc":"brief:0","by":{"0":"3"}},{"t":"case","label":"Pestana v. State","cite":"762 S.E.2d 178","y":2014,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/762/178/","by":{"0":"34"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Preveden v. Hahn","cite":"36 F. Supp. 952","y":1941,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./36/952/","by":{"0":"35"}},{"t":"case","label":"Randall v. Merrill","cite":"820 F.2d 1317","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/820/1317/","by":{"0":"29"}},{"t":"case","label":"Reaume v. Carpenter","cite":"89 N.W. 953","y":1902,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./89/953/","by":{"0":"37"}},{"t":"case","label":"Redman v. United States","cite":"2023 WL 8519201","y":2023,"court":"3d Cir. Dec. 8","by":{"0":"22"}},{"t":"case","label":"Ross v. Eagle Coal Co.","cite":"36 S.W.2d 48","y":1931,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/36/48/","by":{"0":"37"}},{"t":"case","label":"Ruch v. State","cite":"146 N.E. 67","y":1924,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E./146/67/","by":{"0":"18"}},{"t":"case","label":"Rufo v. Inmates of Suffolk County Jail","cite":"502 U.S. 367","y":1992,"id":"1991/90-954","sc":1,"sum":"The Court held that the court does not require a grievous wrong evoked by new and unforeseen change of facts in order to modify a consented decree.","sumSrc":"Oyez","by":{"0":"3","1":"37"}},{"t":"case","label":"Ryan v. Phoenix Ins. Co. of Hartford, Conn.","cite":"215 N.W. 749","y":1927,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W./215/749/","sum":"Noting exception to general rule that a voluntary nonsuit “terminates the jurisdiction of the court” when “the order of dismissal was by counsel without authority to do so”.","sumSrc":"brief:0","by":{"0":"37, 48"}},{"t":"case","label":"S. Grocery Stores v. Cain","cite":"173 S.E. 256","y":1934,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./173/256/","by":{"0":"37"}},{"t":"case","label":"Salazar v. Steelman","cite":"71 P.2d 79","y":1937,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/71/79/","ar":1,"by":{"0":"40","1":"47","2":"18"}},{"t":"case","label":"Schmier v. McDonald’s LLC","cite":"69 F.3d 1240","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/69/1240/","by":{"0":"26, 28"}},{"t":"case","label":"Semtek Int’l Inc. v. Lockheed Martin Corp.","cite":"531 U.S. 497","y":2001,"id":"2000/99-1551","sc":1,"op":1,"sum":"The Court held that \"[b]ecause the claim-preclusive effect of a federal court's dismissal 'upon the merits' of a diversity action on state statute-of-limitations grounds is governed by a federal rule, which in turn (in diversity cases) incorporates the claim-preclusion law that would be applied by state courts in the State in which the federal court sits, the Maryland Court of Special Appeals erred in holding that the California federal court's dismissal 'upon the merits' necessarily precluded the Maryland state-court action.\" Thus, the District Court's dismissal on the merits of claims as untimely under California law did not preclude Semtek from asserting its claims in a different state court forum.","sumSrc":"Oyez","by":{"0":"2, 31"}},{"t":"case","label":"Shreveport Long Leaf Lumber Co. v. Jones","cite":"177 So. 593","y":1937,"court":"La.","url":"https://www.courtlistener.com/c/So./177/593/","by":{"0":"32"}},{"t":"case","label":"Siegfried v. New York, L.E. & W.R. Co.","cite":"34 N.E. 331","y":1893,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E./34/331/","by":{"0":"32"}},{"t":"case","label":"Spellacy v. Superior Ct. in & for Los Angeles Cnty.","cite":"72 P.2d 262","y":1937,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/72/262/","by":{"0":"40"}},{"t":"case","label":"Stonesifer v. Kilburn","cite":"29 P. 332","y":1892,"court":"Cal.","url":"https://www.courtlistener.com/c/P./29/332/","ar":1,"by":{"0":"39","2":"17–18"}},{"t":"case","label":"Storey v. Storey","cite":"221 F. 262","y":1915,"court":"W.D. Wis.","url":"https://www.courtlistener.com/c/F./221/262/","by":{"0":"34"}},{"t":"case","label":"Thompson v. Bay Circuit Judge","cite":"101 N.W. 61","y":1904,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./101/61/","op":4,"ar":6,"by":{"0":"38, 48"}},{"t":"case","label":"Torres v. Oakland Scavenger Co.","cite":"487 U.S. 312","y":1988,"id":"1987/86-1845","sc":1,"sum":"Failure to file a notice of appeal in accordance with Federal Rule of Appellate Procedure 3(c)'s requirement that the notice \"specify the party or parties taking the appeal\" presents a jurisdictional bar to the appeal. The Rule's caveat that an appeal \"shall not be dismissed for [the notice's] informality of form or title\" does not aid petitioner, since his exclusion from the notice constitutes a failure to appeal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Turkiye Halk Bankasi A. S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20"}},{"t":"case","label":"Uhe v. Chicago, M. & St. P. Ry. Co.","cite":"54 N.W. 601","y":1893,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W./54/601/","by":{"0":"25"}},{"t":"case","label":"United States v. Benz","cite":"282 U.S. 304","y":1931,"id":"scdb/1930-114","sc":1,"sum":"Describing this power as the “general rule”.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"case","label":"United States v. Mayer","cite":"235 U.S. 55","y":1914,"id":"scdb/1914-027","sc":1,"sum":"While their jurisdiction is exclusively appellate, Circuit Courts of App.eals may issue writs which are properly auxiliary to their appellate power.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35","1":"14, 44"}},{"t":"case","label":"United States v. Turkette","cite":"452 U.S. 576","y":1981,"id":"1980/80-808","sc":1,"sum":"The term \"enterprise\" as used in RICO encompasses both legitimate and illegitimate enterprises.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"op":1,"sum":"The Court held 8-1 that silent defendant has the burden to satisfy the plain-error rule and unanimously that a reviewing court may consult the whole record when considering the effect of any error on substantial rights.","sumSrc":"Oyez","by":{"0":"13","2":"8"}},{"t":"case","label":"United States v. Whiting","cite":"165 F.3d 631","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/165/631/","by":{"0":"28"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"op":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Walker Bros. Inv., Inc. v. City of Mobile","cite":"252 So. 3d 57","y":2017,"court":"Ala.","url":"https://www.courtlistener.com/c/So.%203d/252/57/","by":{"0":"23"}},{"t":"case","label":"Weinberger v. Romero–Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"sum":"Held that the district court was not obligated to enjoin the Navy from operating on and around Vieques island. He emphasized the traditional flexibility of equitable remedies and courts’ responsibility to balance plaintiffs’ need for an injunction with the public utility of the enjoined action.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"White v. Nat’l Football League","cite":"756 F.3d 585","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/585/","by":{"0":"15, 29","2":"24"}},{"t":"case","label":"Willard v. Wood","cite":"1 App. D.C. 44","y":1893,"court":"App. D.C.","url":"https://www.courtlistener.com/c/App.%20D.C./1/44/","by":{"0":"31","1":"44"}},{"t":"case","label":"Williams v. Frey","cite":"551 F.2d 932","y":1977,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/551/932/","by":{"0":"22"}},{"t":"case","label":"Yesh Music v. Lakewood Church","cite":"727 F.3d 356","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/727/356/","op":1,"ar":1,"by":{"0":"14, 23"}},{"t":"case","label":"Zamora v. Clayborn Contracting Group, Inc.","cite":"47 P.3d 1056","y":2002,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/47/1056/","by":{"0":"41"}},{"t":"case","label":"Zimmerman v. Western Builders’ & Salvage Co.","cite":"297 P. 449","y":1931,"court":"Ariz.","url":"https://www.courtlistener.com/c/P./297/449/","by":{"0":"37"}},{"t":"usc","label":"28 U.S.C. § 2071","url":"https://www.law.cornell.edu/uscode/text/28/2071","stext":{"head":"§2071. Rule-making power generally","paras":[[0,"(a) The Supreme Court and all courts established by Act of Congress may from time to time prescribe rules for the conduct of their business. Such rules shall be consistent with Acts of Congress and rules of practice and procedure prescribed under section 2072 of this title."],[0,"(b) Any rule prescribed by a court, other than the Supreme Court, under subsection (a) shall be prescribed only after giving appropriate public notice and an opportunity for comment. Such rule shall take effect upon the date specified by the prescribing court and shall have such effect on pending proceedings as the prescribing court may order."],[0,"(c)(1) A rule of a district court prescribed under subsection (a) shall remain in effect unless modified or abrogated by the judicial council of the relevant circuit."],[0,"(2) Any other rule prescribed by a court other than the Supreme Court under subsection (a) shall remain in effect unless modified or abrogated by the Judicial Conference."],[0,"(d) Copies of rules prescribed under subsection (a) by a district court shall be furnished to the judicial council, and copies of all rules prescribed by a court other than the Supreme Court under subsection (a) shall be furnished to the Director of the Administrative Office of the United States Courts and made available to the public."],[0,"(e) If the prescribing court determines that there is an immediate need for a rule, such court may proceed under this section without public notice and opportunity for comment, but such court shall promptly thereafter afford such notice and opportunity for comment."],[0,"(f) No rule may be prescribed by a district court other than under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2071?type=usc&year=mostrecent&link-type=html"},"head":"§2071. Rule-making power generally","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 31","1":"45"}},{"t":"rule","label":"Fed. R. Civ. P. 1","url":"https://www.law.cornell.edu/rules/frcp/rule_1","by":{"0":"47","1":"45"}},{"t":"rule","label":"Fed. R. Civ. P. 37","url":"https://www.law.cornell.edu/rules/frcp/rule_37","subs":["(b)"],"by":{"0":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 41","url":"https://www.law.cornell.edu/rules/frcp/rule_41","subs":["(a)","(d)","(a)(1)(A)","(a)(1)(B)"],"by":{"0":"2–9, 11–19, 22–35, 41, 46–49, 21","1":"5, 32, 37, 5, 37","2":"1, 5, 15–16, 23–25, 5, 15, 21, 23–25"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)","(c)","(a)","(c)(1)","(c)(2)","(e)"],"by":{"0":"1, 3, 5–31, 33, 35, 39–49, 20","1":"42, 24, 25, 1, 3, 8, 11, 12, 13, 15, 21, 23, 24, 28, 31, 32, 34, 36, 28, 25, 44","2":"1–9, 15–23, 25, 1–9, 15–17, 19, 21–22"}},{"t":"case","label":"Adair Bus Sales, Inc. v. Blue Bird Corp.","cite":"25 F.3d 953","y":1994,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/25/953/","by":{"1":"4"}},{"t":"case","label":"American States Insurance Co. v. Capital Associates of Jackson County, Inc.","cite":"392 F.3d 939","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/392/939/","by":{"1":"26","2":"12"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"578 U.S. 212","y":2016,"id":"2015/14-770","sc":1,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Bankers Trust Co. v. Mallis","cite":"435 U.S. 381","y":1978,"id":"1977/76-1359","sc":1,"sum":"In dismissing respondents' action against petitioner under § 10 (b) of the Securities Exchange Act of 1934, the District Court failed to set forth the judgment in a separate document as required by Fed. Rule Civ. Proc.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 32","2":"23–24"}},{"t":"case","label":"Barnes v. Whiteman","cite":"9 Dowl. 181","y":1840,"court":"Q.B.","url":"https://www.courtlistener.com/c/Dowl./9/181/","by":{"1":"46"}},{"t":"case","label":"Bender v. Williamsport Area School District","cite":"475 U.S. 534","y":1986,"id":"1985/84-773","sc":1,"ar":2,"sum":"Respondent had no standing to appeal, and therefore the Court of Appeals had no jurisdiction to hear his appeal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 17"}},{"t":"case","label":"Bostwick v. Brinkerhoff","cite":"106 U.S. 3","y":1882,"id":"scdb/1882-004","sc":1,"op":2,"sum":"A judgment of reversal by a State court, with leave for further proceedings in the court of.original jurisdiction, is not subject to review here.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"23","2":"10"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Browder v. Director, Department of Corrections of Illinois","cite":"434 U.S. 257","y":1978,"id":"1977/76-5325","sc":1,"sum":"The Court of Appeals lacked jurisdiction to review the original October 21 order because respondent's motion for a stay and an evidentiary hearing (in essence a motion for rehearing or reconsideration) was untimely under Rule 52 (b) or 59 and hence could not toll the running of the \"mandatory and jurisdictional\" 30-day time limit of Rule 4 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Budinich v. Becton Dickinson & Co.","cite":"486 U.S. 196","y":1988,"id":"1987/87-283","sc":1,"sum":"In petitioner's employment compensation action, which respondent removed from a Colorado state court to the Federal District Court on the basis of diversity of citizenship, judgment was entered on the jury's verdict for petitioner in an amount considerably less than he had sought. Petitioner timely filed new-trial motions and a motion for attorney's fees under Colorado law. On May 14, 1984, the court denied the new …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 28"}},{"t":"case","label":"California v. Texas","cite":"593 U.S. 659","y":2021,"id":"2020/19-840","sc":1,"op":4,"ar":10,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Catlin v. United States","cite":"324 U.S. 229","y":1945,"id":"scdb/1944-071","sc":1,"sum":"1. In a proceeding instituted by a petition in the District Court for the condemnation of land under the War Purposes Act of 1917, a \"judgment\" entered upon a declaration of taking filed pursuant to the Declaration of Taking Act of 1931, and a subsequent order denying the landowner's motion to vacate the judgment and to dismiss the petition, held not \"final decisions\" under § 128 of the Judicial Code and therefore …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 29","2":"10"}},{"t":"case","label":"Central Transportation Co. v. Pullman’s Palace Car Co.","cite":"139 U.S. 24","y":1891,"id":"scdb/1890-151","sc":1,"sum":"A statute of a state, which authorizes the judge presiding at the trial to order a judgment of nonsuit to be entered, when in his opinion the evidence introduced by the plaintiff is insufficient in matter of law to sustain a verdict, may be followed, under Rev. Stat. § 914, in the Circuit Court of the United States held within that state; and a judgment of nonsuitrendered accordingly, upon a ruling in matter of law …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"12, 26","2":"14"}},{"t":"case","label":"Chiarodit v. Chiarodit","cite":"21 P.2d 562","y":1933,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/21/562/","by":{"1":"24"}},{"t":"case","label":"Commissioner v. Bedford’s Estate","cite":"325 U.S. 283","y":1945,"id":"scdb/1944-160","sc":1,"by":{"1":"33","2":"25"}},{"t":"case","label":"Cone v. West Virginia Pulp & Paper Co.","cite":"330 U.S. 212","y":1947,"id":"scdb/1946-056","sc":1,"sum":"Where a party whose motion for a directed verdict has been denied in a federal district court fails, within 10 days after reception of a verdict against him, to make a motion for judgment notwithstanding the verdict, as authorized by Rule 50 (b) of the Federal Rules of Civil Procedure, an appellate court is precluded from directing entry of such a judgment. Pp. 217-218. 153 F. 2d 576, reversed. Petitioner sued …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25, 27, 50","2":"12"}},{"t":"case","label":"Costello v. United States","cite":"365 U.S. 265","y":1961,"id":"1960/59","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Farrar v. Hobby","cite":"506 U.S. 103","y":1992,"id":"1992/91-990","sc":1,"sum":"Petitioners, coadministrators of decedent Farrar's estate, sought $17 million in compensatory damages, pursuant to 42 U. S. C. §§ 1983 and 1985, from respondent Hobby and other Texas public officials for the alleged illegal closure of the school that Farrar and his son operated. However, the Federal District Court awarded them only nominal damages and, subsequently, awarded them $280,000 in attorney's fees under 42 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"1":"23, 41"}},{"t":"case","label":"Frank v. Gaos","cite":"586 U.S. 485","y":2019,"id":"2018/17-961","sc":1,"sum":"This class action settlement case is remanded for the courts below to address the plaintiffs’ standing in light of Spokeo, Inc. v. Robins, 578 U. S. ___.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"op":1,"sum":"In 7-2 opinion delivered by Justice Antonin Scalia, the Court held that Gonzalez's Rule 60(b) motion challenged only the district court's previous ruling on the federal statute of limitations. That motion was therefore not the equivalent of a successive habeas petition and could be ruled on by the district court without the 11th Circuit's precertification.","sumSrc":"Oyez","by":{"1":"19, 48","2":"5"}},{"t":"case","label":"Guam v. United States","cite":"593 U.S. 310","y":2021,"id":"2020/20-382","sc":1,"sum":"A settlement of environmental liabilities must resolve a specific liability under the Comprehensive Environmental Response, Compensation, and Liability Act of 1980 to give rise to a contribution action under that Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"43"}},{"t":"case","label":"Gunn v. Minton","cite":"568 U.S. 251","y":2013,"id":"2012/11-1118","sc":1,"sum":"The Court found that even though federal courts have exclusive jurisdiction over patent law cases, state courts can still hear cases related to patent law as long as that it is not the primary issue.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Hall Street Associates, LLC v. Mattel, Inc.","cite":"552 U.S. 576","y":2008,"id":"2007/06-989","sc":1,"op":1,"sum":"The Court affirmed the Ninth Circuit ruling and held that the provisions of the FAA are exclusive and cannot be expanded through contractual agreement. Writing for the majority, Justice David Souter pointed to words such as \"must\" and \"unless\" in the FAA as evidence that its provisions were intended to be mandatory and incapable of modification by the parties.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Hensley v. Henry","cite":"400 N.E.2d 1352","y":1980,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E.2d/400/1352/","by":{"1":"42"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Jackson v. Merritt","cite":"21 D.C. 276","y":1892,"url":"https://www.courtlistener.com/c/D.C./21/276/","sum":"Holding that “[t]he court will not set aside a non-suit voluntarily suffered by plaintiff ” (citation omitted).","sumSrc":"brief:1","by":{"1":"46"}},{"t":"case","label":"Janssen v. Harris","cite":"321 F.3d 998","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/321/998/","by":{"1":"31"}},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"op":1,"sum":"The term “mistake” in Federal Rule of Civil Procedure 60(b)(1) includes a judge’s errors of law; because Kemp’s motion alleged such an error, it was cognizable under Rule 60(b)(1) and untimely under Rule 60(c)’s 1-year limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"14, 22, 45, 47","2":"17, 19"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Local Loan Co. v. Hunt","cite":"292 U.S. 234","y":1934,"id":"scdb/1933-054","sc":1,"sum":"1. A court of bankruptcy has jurisdiction by ancillary proceedings to enforce an order of discharge by enjoining the prosecution of suits brought against the debtor.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Lundahl v. Halabi","cite":"600 F. App’x 596","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/600/596/","by":{"1":"31"}},{"t":"case","label":"Marshall v. Kansas City Southern Railway Co.","cite":"378 F.3d 495","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/378/495/","ar":1,"by":{"1":"26","2":"12"}},{"t":"case","label":"Melkonyan v. Sullivan","cite":"501 U.S. 89","y":1991,"id":"1990/90-5538","sc":1,"sum":"Petitioner filed suit in the District Court under 42 U. S. C. § 1383(c)(3), which incorporates 42 U. S. C. §405(g)'s review provisions, seeking review of a final decision of respondent Secretary of Health and Human Services denying his application for disability benefits under the Supplemental Security Income program. While his case was pending, he filed a new application, accompanied by additional evidence of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 38"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"582 U.S. 23","y":2017,"id":"2016/15-457","sc":1,"ar":1,"sum":"The Court determined that the federal courts of appeals lack jurisdiction to review an order denying class certification after the named plaintiffs have voluntarily dismissed their claims with prejudice.","sumSrc":"Oyez","by":{"1":"12, 26, 27, 29, 30","2":"12–15"}},{"t":"case","label":"Midland Asphalt Corp. v. United States","cite":"489 U.S. 794","y":1989,"id":"1988/87-1905","sc":1,"sum":"A district court order denying a defendant's motion to dismiss an indictment for an alleged violation of Rule 6(e) is not immediately appealable under § 1291. Since petitioners have not yet been sentenced, the District Court's order is not a final judgment ending the litigation on the merits. Moreover, whatever view is taken of the scope of Mechanik (an issue not resolved here), an order such as that at issue does …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Mohawk Industries, Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Murray v. Marsh","cite":"17 F. Cas. 1059","y":1803,"court":"C.C.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Cas./17/1059/","ar":1,"by":{"1":"44"}},{"t":"case","label":"Owen Equipment & Erection Co. v. Kroger","cite":"437 U.S. 365","y":1978,"id":"1977/77-677","sc":1,"sum":"The District Court had no power to entertain respondent's lawsuit against petitioner as a third-party defendant since diversity jurisdiction was lacking. Gibbs, supra, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Pitchess v. Davis","cite":"421 U.S. 482","y":1975,"id":"1974/74-1128","sc":1,"sum":"Respondent failed to exhaust available state remedies on the claim that formed the basis for the unconditional writ, and hence he is entitled to no relief based upon a claim with respect to which state remedies have not been exhausted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Reno v. Bossier Parish School Board","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"sum":"The Court held that section 5 does not prohibit preclearance of a redistricting plan enacted with a discriminatory but nonretrogressive purpose. \"As we have repeatedly noted, in vote-dilution cases [section 5] prevents nothing but backsliding, and preclearance under [section 5] affirms nothing but the absence of backsliding,\" wrote Justice Scalia.","sumSrc":"Oyez","by":{"1":"23, 29"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Rudolph v. Sensener","cite":"39 App. D.C. 385","y":1912,"url":"https://www.courtlistener.com/c/App.%20D.C./39/385/","by":{"1":"26","2":"14"}},{"t":"case","label":"Sandstrom v. ChemLawn Corp.","cite":"904 F.2d 83","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/904/83/","by":{"1":"38"}},{"t":"case","label":"Simpson v. Brock","cite":"40 S.E. 266","y":1901,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./40/266/","by":{"1":"46"}},{"t":"case","label":"SmartSky Networks, LLC v. DAG Wireless, Ltd.","cite":"93 F.4th 175","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/93/175/","by":{"1":"39"}},{"t":"case","label":"Smith v. Spizzirri","cite":"601 U.S. 472","y":2024,"id":"2023/22-1218","sc":1,"op":1,"sum":"When a district court finds that a lawsuit involves an arbitrable dispute and a party has requested a stay of the court proceeding pending arbitration, §3 of the Federal Arbitration Act, 9 U. S. C. §3, compels the court to issue a stay, and the court lacks discretion to dismiss the suit.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"4, 40"}},{"t":"case","label":"Smurda v. Superior Court","cite":"266 P. 843","y":1928,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/P./266/843/","by":{"1":"47","2":"18"}},{"t":"case","label":"Snyder v. Harris","cite":"394 U.S. 332","y":1969,"id":"1968/109","sc":1,"sum":"Separate and distinct claims presented by and for various claimants in federal diversity actions may not be added together to provide the requisite $10,000 jurisdictional amount in controversy. Fed. Rule Civ. Proc. 23, as amended in 1966, did not change the scope of the statutory grant of district court jurisdiction, as the longstanding judicial interpretation of that statute cannot be changed by an amendment to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Southern Railway Co. v. Miller","cite":"217 U.S. 209","y":1910,"id":"scdb/1909-128","sc":1,"sum":"Far the purp^.v’s vi determining the removability of á cause, the case most be de.med to be stsch as the plaintiff has made it, in good faith, in his pteadVr?; r.nd if a plaintiff in a suit for personal injuries joined with the &}<<*$). corporation one or more of its employes residents of plaintiff’s State as defendants, and the state court holds that, the joinder is -wt improper, the cause is not separable and …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"id":"2021/21-309","sc":1,"op":1,"sum":"Airplane cargo loaders and ramp supervisors who, like petitioner Saxon, frequently load and unload airplane cargo belong to a “class of workers engaged in foreign or interstate commerce” exempt from the Federal Arbitration Act’s coverage.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"ar":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25","2":"9"}},{"t":"case","label":"Summers v. Earth Island Institute","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"592 U.S. 43","y":2020,"id":"2020/19-71","sc":1,"sum":"The Religious Freedom Restoration Act of 1993’s express remedies provision, see 42 U. S. C. §2000bb–1(c), permits litigants, when appropriate, to obtain money damages against federal officials in their individual capacities.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"sum":"The judgment is affirmed. 820 F. 2d 832, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Treasurer of State of Michigan v. Barry","cite":"168 F.3d 8","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/168/8/","by":{"1":"26","2":"12"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"ar":1,"sum":"The Court held that the Court of Appeals erred in concluding that this was a sufficient basis to justify reopening the judgment. \"[A]n independent action should be available only to prevent a grave miscarriage of justice,\" wrote Chief Justice Rehnquist, \"it should be obvious that [the Beggerlys'] allegations do not nearly approach this demanding standard.\" The Court also concluded that the Court of Appeals extension of the Quiet Title Act's statutory period by equitable tolling was unwarranted, given its generous nature.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"United States v. L-3 Communications EOTech, Inc.","cite":"921 F.3d 11","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/921/11/","by":{"1":"38"}},{"t":"case","label":"United States v. Merz","cite":"376 U.S. 192","y":1964,"id":"1963/65","sc":1,"sum":"Under Rule 71A (h) of the Federal Rules of Civil Procedure, Commissions were appointed by district courts to determine the issue of just compensation in eminent domain proceedings. Following hearings, reports were filed by the Commissioners, which the District Court adopted in each instance, though the reports did not disclose the basis on which the awards were reached. One Court of Appeals affirmed, finding the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Weisguth v. Supreme Tribe of Ben Hur","cite":"112 N.E. 350","y":1916,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E./112/350/","by":{"1":"14, 46"}},{"t":"case","label":"Wetmore v. Karrick","cite":"205 U.S. 141","y":1907,"id":"scdb/1906-144","sc":1,"sum":"Where an action is brought to recover upon a judgment the jurisdiction of the court rendering the judgment is open to inquiry; and the Constitutional requirement as to full faith and credit in each State to be given the public acts, records and judicial proceedings of every other State does not require the enforcement of a judgment rendered without jurisdiction or otherwise wanting in due process of law.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Wilson v. Republic Iron & Steel Co.","cite":"257 U.S. 92","y":1921,"id":"scdb/1921-013","sc":1,"sum":"1. Whether a District Court into which a case has been removed from a state court may retain the case and proceed to its adjudication; or must remand it to the court whence it came, is a jurisdictional question a decision of which sustaining the jurisdiction may be reviewed here by direct writ of error, under Jud. Code, § 238, after final judgment.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24","2":"9, 10, 21"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","by":{"1":"4"}},{"t":"usc","label":"9 U.S.C. § 10","url":"https://www.law.cornell.edu/uscode/text/9/10","stext":{"head":"§10. Same; vacation; grounds; rehearing","paras":[[0,"(a) In any of the following cases the United States court in and for the district wherein the award was made may make an order vacating the award upon the application of any party to the arbitration—"],[1,"(1) where the award was procured by corruption, fraud, or undue means;"],[1,"(2) where there was evident partiality or corruption in the arbitrators, or either of them;"],[1,"(3) where the arbitrators were guilty of misconduct in refusing to postpone the hearing, upon sufficient cause shown, or in refusing to hear evidence pertinent and material to the controversy; or of any other misbehavior by which the rights of any party have been prejudiced; or"],[1,"(4) where the arbitrators exceeded their powers, or so imperfectly executed them that a mutual, final, and definite award upon the subject matter submitted was not made."],[0,"(b) If an award is vacated and the time within which the agreement required the award to be made has not expired, the court may, in its discretion, direct a rehearing by the arbitrators."],[0,"(c) The United States district court for the district wherein an award was made that was issued pursuant to section 580 of title 5 may make an order vacating the award upon the application of a person, other than a party to the arbitration, who is adversely affected or aggrieved by the award, if the use of arbitration or the award is clearly inconsistent with the factors set forth in section 572 of title 5."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/10?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§10. Same; vacation; grounds; rehearing","tname":"Arbitration","by":{"1":"2, 6"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"1":"23, 26, 32","2":"6–7, 12–13, 21–23"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(a)"],"by":{"1":"17"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","by":{"1":"35"}},{"t":"rule","label":"Fed. R. App. P. 4","url":"https://www.law.cornell.edu/rules/frap/rule_4","subs":["(a)(4)(A)(vi)"],"by":{"1":"25"}},{"t":"rule","label":"Fed. R. Civ. P. 2","url":"https://www.law.cornell.edu/rules/frcp/rule_2","by":{"1":"33"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(a)"],"by":{"1":"13, 32, 33","2":"24"}},{"t":"rule","label":"Fed. R. Civ. P. 55","url":"https://www.law.cornell.edu/rules/frcp/rule_55","subs":["(c)"],"by":{"1":"42"}},{"t":"rule","label":"Fed. R. Civ. P. 58","url":"https://www.law.cornell.edu/rules/frcp/rule_58","subs":["(a)","(b)"],"by":{"1":"33, 35, 33","2":"23–24"}},{"t":"rule","label":"Fed. R. Civ. P. 69","url":"https://www.law.cornell.edu/rules/frcp/rule_69","by":{"1":"36, 43"}},{"t":"rule","label":"Fed. R. Civ. P. 71.1","url":"https://www.law.cornell.edu/rules/frcp/rule_71.1","by":{"1":"36"}},{"t":"rule","label":"Fed. R. Civ. P. 79","url":"https://www.law.cornell.edu/rules/frcp/rule_79","subs":["(b)"],"by":{"1":"41"}},{"t":"rule","label":"Fed. R. Civ. P. 82","url":"https://www.law.cornell.edu/rules/frcp/rule_82","by":{"1":"11, 19"}},{"t":"case","label":"Allied Air Freight, Inc. v. Pan Am. World Airways, Inc.","cite":"393 F.3d 441","y":1968,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/393/441/","by":{"2":"11–12"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"City of Sherrill, N.Y. v. Oneida Indian Nation of New York","cite":"544 U.S. 197","y":2005,"id":"2004/03-855","sc":1,"sum":"The Court held that standards of federal Indian law and federal equity precluded the Tribe from unilaterally reviving its ancient sovereignty over the land at issue.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"HollyFrontier Cheyenne Ref., LLC v. Renewable Fuels Ass’n","cite":"594 U.S. 382","y":2021,"id":"2020/20-472","sc":1,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"7–8"}},{"t":"case","label":"Kelly v. Great Atl. & Pac. Tea Co.","cite":"86 F.2d 296","y":1936,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/86/296/","by":{"2":"13, 22"}},{"t":"case","label":"Lauderdale-El v. Indiana Parole Bd.","cite":"35 F.4th 572","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/35/572/","by":{"2":"11"}},{"t":"case","label":"LeCompte, v. Mr. Chip, Inc.","cite":"528 F.2d 601","y":1976,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/528/601/","by":{"2":"14"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"586 U.S. 188","y":2019,"id":"2018/17-1094","sc":1,"sum":"Federal Rule of Civil Procedure 23(f), which establishes a 14-day deadline to seek permission to appeal an order granting or denying class certification, is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"1–3"}},{"t":"case","label":"Pac. Bell Tel. Co. v. linkLine Commc’ns, Inc.","cite":"555 U.S. 438","y":2009,"id":"2008/07-512","sc":1,"sum":"The Court held that a \"price squeezing\" claim cannot be brought under Section 2 of the Sherman Act when the defendant is not under a duty to sell to the plaintiff in the first place.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"PennEast Pipeline Company, LLC v. New Jersey","cite":"594 U.S. 482","y":2021,"id":"2020/19-1039","sc":1,"sum":"A certificate of public convenience and necessity issued by the Federal Energy Regulatory Commission pursuant to §717f(h) of the Natural Gas Act authorizes a private company to condemn all necessary rights-of-way, whether owned by private parties or States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"3"}},{"t":"case","label":"Rinieri v. News Syndicate Co.","cite":"385 F.3d 818","y":1967,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/385/818/","by":{"2":"11"}},{"t":"case","label":"Truck Ins. Exch. v. Kaiser Gypsum Co., Inc.","cite":"602 U.S. 268","y":2024,"id":"2023/22-1079","sc":1,"sum":"An insurer with financial responsibility for bankruptcy claims is a “party in interest” under 11 U. S. C. §1109(b) that “may raise and may appear and be heard on any issue” in a Chapter 11 case.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"17"}},{"t":"case","label":"United States v. Evans","cite":"9 U.S. 280","y":1809,"id":"scdb/1809-015","sc":1,"op":1,"sum":"it is not a ground for a writ of error that the judge to'reinstau^a cause after nonsmL","sumSrc":"Headnote (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"United States v. Stitt","cite":"586 U.S. 27","y":2018,"id":"2018/17-765","sc":1,"sum":"The term “burglary” in the Armed Career Criminal Act includes burglary of a structure or vehicle that has been adapted or is customarily used for overnight accommodation.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"2"}},{"t":"case","label":"Wecker v. Nat’l Enameling & Stamping Co.","cite":"204 U.S. 176","y":1907,"id":"scdb/1906-207","sc":1,"sum":"Where the Circuit Court refuses to. remand, and on the plaintiff declining to recognize its jurisdiction or proceed, dismisses the case and renders judgment that plaintiff take nothing thereby and defendant go hence without day and recover his costs, the judgment is final, so far as that suit is concerned, and the question of jurisdiction can be certified to this court under § 5 of the act of March 3, 1891, 26 Stat. …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"usc","label":"28 U.S.C. § 225","url":"https://www.law.cornell.edu/uscode/text/28/225","subs":["(a)(1946)"],"by":{"2":"6–7"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)"],"by":{"2":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(f)"],"by":{"2":"13"}},{"t":"rule","label":"Fed. R. Civ. P. 62","url":"https://www.law.cornell.edu/rules/frcp/rule_62","by":{"2":"20–21"}},{"t":"rule","label":"Fed. R. Civ. P. 68","url":"https://www.law.cornell.edu/rules/frcp/rule_68","by":{"2":"24"}}]};